#!/usr/bin/env python3
"""
Catches up your repo with two fixes that never actually landed:

1. Backblaze B2 storage - you set the B2_* env vars on Render, but the
   Django code that actually uses them (production.py + requirements.txt)
   was missing, so uploads were still hitting local disk, not B2.
2. The sidebar nav bug fix (Movies/My Movies both highlighting at once)
   - the original buggy version was still in the repo.

Usage (run from the project ROOT):
    cd mdm-project-main
    python apply_missing_fixes.py

Then:
    cd backend && venv\\Scripts\\pip install -r requirements.txt   (Windows)
    or venv/bin/pip install -r requirements.txt                    (macOS/Linux)
    cd ..
    git add -A
    git commit -m "Add B2 storage config and sidebar nav fix"
    git push
"""

import os
import shutil
import sys

FILES = {}

FILES['backend/requirements.txt'] = 'Django==5.1.3\ndjangorestframework==3.15.2\ndjangorestframework-simplejwt==5.3.1\npsycopg2-binary==2.9.10\npython-decouple==3.8\ndjango-cors-headers==4.6.0\ndjango-filter==24.3\ndrf-spectacular==0.27.2\nPillow==11.0.0\ndj-database-url==2.3.0\ngunicorn==23.0.0\nwhitenoise==6.8.2\ndjango-ranged-response==0.2.0\ndjango-storages==1.14.4\nboto3==1.35.99\n'

FILES['backend/config/settings/production.py'] = '"""Production settings. Import everything from base and harden it."""\nfrom decouple import config\nfrom .base import *  # noqa: F401,F403\n\nDEBUG = False\n\n# --- HTTPS / cookie hardening ---\nSECURE_SSL_REDIRECT = config(\'SECURE_SSL_REDIRECT\', default=True, cast=bool)\nSESSION_COOKIE_SECURE = True\nCSRF_COOKIE_SECURE = True\nSECURE_HSTS_SECONDS = 60 * 60 * 24 * 30  # 30 days\nSECURE_HSTS_INCLUDE_SUBDOMAINS = True\nSECURE_HSTS_PRELOAD = True\nSECURE_CONTENT_TYPE_NOSNIFF = True\nSECURE_BROWSER_XSS_FILTER = True\nX_FRAME_OPTIONS = \'DENY\'\n\n# Only the JSON renderer in production — no browsable API exposing DB internals.\nREST_FRAMEWORK[\'DEFAULT_RENDERER_CLASSES\'] = (  # noqa: F405\n    \'rest_framework.renderers.JSONRenderer\',\n)\n\n# --- Movie/poster file storage: Backblaze B2 (S3-compatible) ---\n# Render\'s disk doesn\'t persist across deploys/restarts, so uploaded videos\n# and posters can\'t live in the local filesystem here the way they do in\n# dev. django-storages\' S3-compatible backend works with B2 directly — B2\n# just needs its own endpoint/region instead of AWS\'s.\nSTORAGES[\'default\'] = {  # noqa: F405\n    \'BACKEND\': \'storages.backends.s3.S3Storage\',\n}\n\nAWS_ACCESS_KEY_ID = config(\'B2_KEY_ID\')\nAWS_SECRET_ACCESS_KEY = config(\'B2_APPLICATION_KEY\')\nAWS_STORAGE_BUCKET_NAME = config(\'B2_BUCKET_NAME\')\nAWS_S3_ENDPOINT_URL = config(\'B2_ENDPOINT_URL\')  # e.g. https://s3.us-west-004.backblazeb2.com\nAWS_S3_REGION_NAME = config(\'B2_REGION_NAME\')  # e.g. us-west-004\nAWS_S3_ADDRESSING_STYLE = \'virtual\'\nAWS_S3_FILE_OVERWRITE = False  # don\'t clobber a file if two uploads share a name\n\n# The bucket stays private — the app already has a "private" vs "public"\n# visibility concept for uploaded movies, so files shouldn\'t be publicly\n# readable by anyone who has (or guesses) the URL. Instead every file URL\n# is signed and expires, so a link only works briefly and only via a URL\n# this app itself generated.\nAWS_DEFAULT_ACL = None\nAWS_QUERYSTRING_AUTH = True\nAWS_QUERYSTRING_EXPIRE = 3600  # signed URLs expire after 1 hour\n'

FILES['frontend/components/layout/Sidebar.tsx'] = '\'use client\';\n\nimport Link from \'next/link\';\nimport { usePathname } from \'next/navigation\';\nimport { LogOut, Settings, User as UserIcon } from \'lucide-react\';\nimport { primaryNavItems } from \'./nav-items\';\nimport { useAuth } from \'@/hooks/useAuth\';\nimport { cn } from \'@/lib/utils\';\n\n/**\n * Desktop-only left sidebar (spec section 5). Hidden below the `lg` breakpoint,\n * where MobileNav takes over via a drawer instead.\n */\nexport function Sidebar() {\n  const pathname = usePathname();\n  const { user, logout } = useAuth();\n\n  return (\n    <aside className="hidden lg:flex lg:w-64 lg:flex-col lg:border-r lg:border-border lg:bg-surface">\n      <div className="flex h-16 items-center gap-2 px-6">\n        <span className="font-display text-lg font-medium tracking-tight text-foreground">\n          Movie Manager\n        </span>\n      </div>\n\n      <nav aria-label="Primary" className="flex flex-1 flex-col gap-1 px-3">\n        {primaryNavItems.map((item) => {\n          const isActive = pathname === item.href || pathname.startsWith(`${item.href}/`);\n          const Icon = item.icon;\n          return (\n            <Link\n              key={item.href}\n              href={item.href}\n              aria-current={isActive ? \'page\' : undefined}\n              className={cn(\n                \'flex items-center gap-3 rounded-lg px-3 py-2 text-sm font-medium transition-colors\',\n                isActive\n                  ? \'bg-accent-soft text-accent\'\n                  : \'text-foreground-muted hover:bg-surface-raised hover:text-foreground\'\n              )}\n            >\n              <Icon size={18} strokeWidth={2} />\n              {item.label}\n            </Link>\n          );\n        })}\n      </nav>\n\n      <div className="px-3 pb-4">\n        <div className="sprocket-rail mb-3" />\n\n        <Link\n          href="/settings"\n          className="flex items-center gap-3 rounded-lg px-3 py-2 text-sm font-medium text-foreground-muted transition-colors hover:bg-surface-raised hover:text-foreground"\n        >\n          <UserIcon size={18} strokeWidth={2} />\n          <span className="truncate">{user?.username ?? \'Profile\'}</span>\n        </Link>\n        <Link\n          href="/settings"\n          className="flex items-center gap-3 rounded-lg px-3 py-2 text-sm font-medium text-foreground-muted transition-colors hover:bg-surface-raised hover:text-foreground"\n        >\n          <Settings size={18} strokeWidth={2} />\n          Settings\n        </Link>\n        <button\n          onClick={logout}\n          className="flex w-full items-center gap-3 rounded-lg px-3 py-2 text-left text-sm font-medium text-foreground-muted transition-colors hover:bg-danger/10 hover:text-danger"\n        >\n          <LogOut size={18} strokeWidth={2} />\n          Logout\n        </button>\n      </div>\n    </aside>\n  );\n}\n'

FILES['frontend/components/layout/MobileNav.tsx'] = '\'use client\';\n\nimport { useEffect, useState } from \'react\';\nimport Link from \'next/link\';\nimport { usePathname } from \'next/navigation\';\nimport { LogOut, Menu, Settings, User as UserIcon, X } from \'lucide-react\';\nimport { primaryNavItems } from \'./nav-items\';\nimport { useAuth } from \'@/hooks/useAuth\';\nimport { useFocusTrap } from \'@/hooks/useFocusTrap\';\nimport { cn } from \'@/lib/utils\';\n\n/**\n * Mobile top bar with a slide-out drawer, shown below the `lg` breakpoint\n * (spec section 5: "responsive navigation menu / drawer" on mobile).\n */\nexport function MobileNav() {\n  const [isOpen, setIsOpen] = useState(false);\n  const pathname = usePathname();\n  const { user, logout } = useAuth();\n  const drawerRef = useFocusTrap(isOpen);\n\n  useEffect(() => {\n    if (!isOpen) return;\n    const onKey = (e: KeyboardEvent) => e.key === \'Escape\' && setIsOpen(false);\n    document.addEventListener(\'keydown\', onKey);\n    return () => document.removeEventListener(\'keydown\', onKey);\n  }, [isOpen]);\n\n  return (\n    <div className="lg:hidden">\n      <div className="flex h-14 items-center justify-between border-b border-border bg-surface px-4">\n        <span className="font-display text-base font-medium tracking-tight text-foreground">\n          Movie Manager\n        </span>\n        <button\n          onClick={() => setIsOpen(true)}\n          aria-label="Open menu"\n          className="icon-btn-focus rounded-md p-2 text-foreground-muted hover:bg-surface-raised hover:text-foreground"\n        >\n          <Menu size={22} />\n        </button>\n      </div>\n\n      {isOpen && (\n        <div className="fixed inset-0 z-50 flex">\n          {/* Backdrop */}\n          <button\n            aria-label="Close menu"\n            className="absolute inset-0 bg-black/60"\n            onClick={() => setIsOpen(false)}\n          />\n\n          {/* Drawer */}\n          <div\n            ref={drawerRef}\n            tabIndex={-1}\n            role="dialog"\n            aria-modal="true"\n            aria-label="Navigation menu"\n            className="relative flex h-full w-72 flex-col bg-surface shadow-xl focus:outline-none"\n          >\n            <div className="flex h-14 items-center justify-between px-4">\n              <span className="font-display text-base font-medium text-foreground">Movie Manager</span>\n              <button\n                onClick={() => setIsOpen(false)}\n                aria-label="Close menu"\n                className="icon-btn-focus rounded-md p-2 text-foreground-muted hover:bg-surface-raised hover:text-foreground"\n              >\n                <X size={20} />\n              </button>\n            </div>\n\n            <nav aria-label="Primary" className="flex flex-1 flex-col gap-1 overflow-y-auto px-3">\n              {primaryNavItems.map((item) => {\n                const isActive = pathname === item.href || pathname.startsWith(`${item.href}/`);\n                const Icon = item.icon;\n                return (\n                  <Link\n                    key={item.href}\n                    href={item.href}\n                    onClick={() => setIsOpen(false)}\n                    aria-current={isActive ? \'page\' : undefined}\n                    className={cn(\n                      \'flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors\',\n                      isActive\n                        ? \'bg-accent-soft text-accent\'\n                        : \'text-foreground-muted hover:bg-surface-raised hover:text-foreground\'\n                    )}\n                  >\n                    <Icon size={18} strokeWidth={2} />\n                    {item.label}\n                  </Link>\n                );\n              })}\n            </nav>\n\n            <div className="px-3 pb-6">\n              <div className="sprocket-rail mb-3" />\n              <Link\n                href="/settings"\n                onClick={() => setIsOpen(false)}\n                className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium text-foreground-muted hover:bg-surface-raised hover:text-foreground"\n              >\n                <UserIcon size={18} strokeWidth={2} />\n                <span className="truncate">{user?.username ?? \'Profile\'}</span>\n              </Link>\n              <Link\n                href="/settings"\n                onClick={() => setIsOpen(false)}\n                className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium text-foreground-muted hover:bg-surface-raised hover:text-foreground"\n              >\n                <Settings size={18} strokeWidth={2} />\n                Settings\n              </Link>\n              <button\n                onClick={() => {\n                  setIsOpen(false);\n                  logout();\n                }}\n                className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm font-medium text-foreground-muted hover:bg-danger/10 hover:text-danger"\n              >\n                <LogOut size={18} strokeWidth={2} />\n                Logout\n              </button>\n            </div>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n'

def main():
    root = os.getcwd()
    if not os.path.isdir(os.path.join(root, 'backend')) or not os.path.isdir(os.path.join(root, 'frontend')):
        print('Error: run this script from the project root (must contain backend/ and frontend/ folders).')
        sys.exit(1)
    print('Backing up files that will be changed (.bak)...')
    for rel_path in FILES:
        full_path = os.path.join(root, rel_path)
        if os.path.exists(full_path):
            shutil.copyfile(full_path, full_path + '.bak')
    for rel_path, content in FILES.items():
        full_path = os.path.join(root, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        print(f'Writing {rel_path}...')
        with open(full_path, 'w', encoding='utf-8', newline='\n') as f:
            f.write(content)
    print()
    print('Done. Next steps:')
    print('  1. cd backend, reinstall requirements (pip install -r requirements.txt)')
    print('  2. git add -A && git commit -m "Add B2 storage config and sidebar nav fix" && git push')
    print()
    print('Backups of the original files were saved alongside them as *.bak')

if __name__ == '__main__':
    main()
